from pagination import merge_pages

first = {'id': 'a', 'old': 1}
last = {'id': 'a', 'nested': []}
b = {'id': 'b', 'v': 1}
b_last = {'id': 'b', 'v': 2}
c = {'id': 'c'}
pages = [[first, b, last], [], [c, b_last]]
result = merge_pages((iter(page) for page in pages))
assert result == [last, b_last, c]
assert all(output is not original for output, original in zip(result, [last, b_last, c]))
assert result[0]['nested'] is last['nested']
assert first == {'id': 'a', 'old': 1}
assert b == {'id': 'b', 'v': 1}
assert merge_pages(iter(())) == []
assert merge_pages(iter([iter(())])) == []
assert merge_pages([[{'id': 'a'}]]) == [{'id': 'a'}]
print('Additional checks passed: duplicates within/across pages, generators, shallow copies, empty input, independent calls.')
